 function bindTools(){const q=document.querySelector('#map-search');q.value=state.query;q.oninput=()=>{state.query=q.value;draw();results();};document.querySelectorAll('[data-map-layer]').forEach(b=>{b.checked=state.layers[b.dataset.mapLayer];b.onchange=()=>{state.layers[b.dataset.mapLayer]=b.checked;draw();};});document.querySelectorAll('[data-map-category]').forEach(b=>{b.checked=state.categories.includes(b.dataset.mapCategory);b.onchange=()=>{state.categories=[...document.querySelectorAll('[data-map-category]:checked')].map(x=>x.dataset.mapCategory);draw();results(true);};});document.querySelector('[data-map-all]').onclick=()=>{state.categories=[];state.district=null;document.querySelectorAll('[data-map-category]').forEach(x=>x.checked=false);draw();results(true);};document.querySelector('[data-map-clear-filter]').onclick=document.querySelector('[data-map-all]').onclick;document.querySelectorAll('[data-map-action]').forEach(b=>b.onclick=async()=>{try{switch(b.dataset.mapAction){case 'zoom-in':map.zoomIn(.5);break;case 'zoom-out':map.zoomOut(.5);break;case 'reset':reset();break;case 'party':if(data.party?.position)map.setView(D.latlng(data.party.position),Math.max(map.getZoom(),-1));else message('Положение группы ещё не задано');break;case 'refresh':await load();break;case 'fullscreen':{const el=document.querySelector('.city-map-ui');if(document.fullscreenElement)await document.exitFullscreen();else if(el.requestFullscreen)await el.requestFullscreen();else{el.classList.toggle('is-fullscreen');map.invalidateSize();}break;}case 'route-panel':if(!data.party?.position)message('Сначала Мастер должен задать положение группы');else{state.query='';state.district=null;state.categories=[];q.value='';results(true);message('Выбери локацию и нажми «Построить маршрут»');}break;}}catch(e){message(e.message);}});}
